package cn.gov.document.platform.document.api;import cn.gov.document.platform.common.api.ApiResponse;import cn.gov.document.platform.document.application.DocumentService;import cn.gov.document.platform.writing.api.WritingQaDtos;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/writing-tasks/{taskId}/qa")public class QaInsertionController{private final DocumentService service;public QaInsertionController(DocumentService service){this.service=service;}@PostMapping("/{qaId}/insert")ApiResponse<DocumentDtos.DocumentResponse>insert(@PathVariable String taskId,@PathVariable String qaId,@Valid @RequestBody WritingQaDtos.InsertRequest request){return ApiResponse.success(service.insertQaAnswer(taskId,qaId,request));}}
